param([string]$Results='Temp/MillionScaleExecution/resident-time')
$ErrorActionPreference='Stop';$root=Split-Path $PSScriptRoot -Parent;. (Join-Path $PSScriptRoot 'ProjectLayout.ps1');$out=Join-Path $root $Results;if(Test-Path -LiteralPath $out){throw 'Fresh output required'};New-Item -ItemType Directory -Path $out|Out-Null
$source=Join-Path $out 'CityCoreResidents.baseline.cs';$old=& git -C $root show '405fd8e:Assets/Scripts/Runtime/Simulation/Residents/CityCoreResidents.cs';if($LASTEXITCODE -ne 0){throw 'Frozen source missing'};[IO.File]::WriteAllLines($source,$old)
